class AsyncAgentResource:
    """Operations on agent."""

    def __init__(self, client: AsyncAPIClient) -> None:
        self._client = client

    async def signup(
        self,
        params: AgentSignupRequest,
        *,
        extra_headers: Mapping[str, str] | None = None,
        timeout: float | httpx.Timeout | None = None,
    ) -> AgentSignupResponse:
        """Sign up as an agent.

        BillionSend extension, no API key needed. Creates an account for an agent
        without a person present: a team named after the agent, one inbox on the shared
        domain (no DNS) and an inbox-scoped key for it, so the agent can receive mail at
        once. The account is **unclaimed**: it only receives, and every send answers 403
        `team_unclaimed`. A claim link goes to `human_email`; the person opens it, signs
        in and claims the account, which becomes theirs on the Free plan (the key keeps
        working, as an inbox-scoped key under their team). An account nobody claims
        deletes itself 7 days after signup. Limits: 3 signups per client address per
        hour, 100 per hour in all, 3 per `human_email` per day.

        ``POST /agent/signup``
        """
        response = await self._client.request(
            "POST",
            "/agent/signup",
            body=params,
            auth=False,
            extra_headers=extra_headers,
            timeout=timeout,
        )
        return cast("AgentSignupResponse", response)

    async def status(
        self,
        *,
        extra_headers: Mapping[str, str] | None = None,
        timeout: float | httpx.Timeout | None = None,
    ) -> AgentAccountStatus:
        """Get the account's claim status.

        BillionSend extension. Whether the account behind the key is still unclaimed,
        when it deletes itself, and what it may do meanwhile. Any key may ask; an
        account a person has claimed answers `claimed` with no limits.

        ``GET /agent/status``
        """
        response = await self._client.request(
            "GET",
            "/agent/status",
            extra_headers=extra_headers,
            timeout=timeout,
        )
        return cast("AgentAccountStatus", response)

    async def claim_email(
        self,
        *,
        extra_headers: Mapping[str, str] | None = None,
        timeout: float | httpx.Timeout | None = None,
    ) -> AgentClaimEmail:
        """Send the claim link again.

        BillionSend extension. Sends the claim link to the address given at signup
        again; the earlier link stops working. At most 5 claim emails in all, ten
        minutes apart.

        ``POST /agent/claim-email``
        """
        response = await self._client.request(
            "POST",
            "/agent/claim-email",
            extra_headers=extra_headers,
            timeout=timeout,
        )
        return cast("AgentClaimEmail", response)


